// গুগল শিট থেকে আসা সব সারি (Rows) প্রসেস করা
const items = $input.all();

return items.map(row => {
  const data = row.json;
  const stock = Number(data.current_stock || 0);
  const rop = Number(data.reorder_point || 0);
  const orderQty = Number(data.reorder_qty || 500);
  const currentStatus = (data.status || "").toUpperCase();

  // যদি স্টক কম থাকে এবং ইতিমধ্যে অর্ডার করা না হয়ে থাকে
  const needsReorder = (stock <= rop) && (currentStatus !== "ORDERED");

  return {
    json: {
      row_number: data.row_number,
      sku: data.sku,
      item: data.item,
      current_stock: stock,
      reorder_point: rop,
      reorder_qty: orderQty,
      vendor_email: data.vendor_email,
      needs_reorder: needsReorder,
      status: needsReorder ? "REORDER_NEEDED" : (currentStatus === "ORDERED" ? "ORDERED" : "SUFFICIENT")
    }
  };
});

