const items = $input.all();
const prevItems =$('Filter Items to Reorder').all();

return items.map((item, index) => {
  let rawText = item.json.content?.parts?.[0]?.text || item.json.text || "{}";
  rawText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

  let parsed = { subject: "Purchase Order Request", body: rawText };
  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    // Fallback if not strict JSON
  }

  const originalData = prevItems[index].json;

  return {
    json: {
      ...originalData,
      email_subject: parsed.subject,
      email_body: parsed.body,
      order_date: new Date().toISOString().split('T')[0]
    }
  };
});
